Task: Pull energy from every cell and return the total.
Signature: int total_energy(int cells[], int n)

Student code:
```c
/* Helper function to add two given values. */
int add_values(int first_value, int second_value)
{
    /* Return the sum of the two values. */
    return (first_value + second_value);
}

/* Return the sum of the n values in cells. */
int total_energy(int cells[], int n)
{
    /* Declare a variable to keep the running total. */
    int running_total = 0;
    /* Declare a variable to move through the array positions. */
    int position = 0;

    /* Visit each position of the cells array. */
    for (position = 0; position <= n; position = position + 1)
    {
        /* Add the current cell value to the running total. */
        running_total = add_values(running_total, cells[position]);
    }

    /* Return the final total energy. */
    return (running_total);
}
